const t=[{id:"1",slug:"en-planmed-financiamos-pensionados",title:"EN PLANMED FINANCIAMOS: PENSIONADOS",excerpt:"Muchas personas pensionadas también desean realizarse procedimientos estéticos y hoy pueden acceder a opciones de financiación adaptadas a su perfil. Requisitos...",coverImage:"/images/branding/logo_fondo_transparente.png",content:"<p>Si eres pensionado y deseas realizarte un procedimiento estético, en Planmed contamos con opciones de financiación adaptadas a tu perfil. Evaluamos tu capacidad de pago basándonos en tus ingresos pensionales.</p><h2>Requisitos básicos</h2><ul><li>Copia de la cédula de ciudadanía.</li><li>Últimos desprendibles de pago de pensión.</li><li>Extractos bancarios.</li></ul><p>Nuestro equipo de asesores te acompañará en cada paso para asegurar que tu plan de pago sea viable y cómodo.</p>",publishedAt:"2026-05-15T21:08:20+00:00",author:"gerencia Planmed",seo:{metaTitle:"FINANCIACION CIRUGIA PLASTICA - FINANCIAMOS PENSIONADOS",metaDescription:"Muchas personas pensionadas también desean realizarse procedimientos estéticos y hoy pueden acceder a opciones de financiación adaptadas a su perfil. Requisitos..."}},{id:"2",slug:"una-cirugia-es-un-gasto-o-una-inversion-la-decision-que-muchos-estan-replanteando",title:"¿Una cirugía es un gasto o una inversión? La decisión que muchos están replanteando",excerpt:"Descubre por qué cada vez más personas consideran que invertir en su bienestar físico y emocional a través de la cirugía plástica es una decisión transformadora.",coverImage:"/images/branding/logo_fondo_transparente.png",content:"<p>Históricamente, la cirugía plástica se ha visto como un lujo. Sin embargo, en la actualidad, muchas personas han comenzado a verla como una inversión en su bienestar, salud mental y calidad de vida.</p><h2>El impacto emocional</h2><p>Más allá del cambio físico, los pacientes reportan un aumento significativo en su autoestima y confianza. Esto se traduce en un mejor desempeño laboral y relaciones interpersonales más saludables.</p><h2>Financiación inteligente</h2><p>Con herramientas como las que ofrece Planmed, no es necesario descapitalizarse. Diseñar un plan de pagos permite obtener los beneficios hoy y pagarlos a un ritmo manejable.</p>",publishedAt:"2026-04-21T14:48:37+00:00",author:"Planmed"},{id:"3",slug:"antes-y-despues-paciente-feliz-con-mamoplastia",title:"ANTES Y DESPUÉS PACIENTE FELIZ CON MAMOPLASTIA",excerpt:"Conoce la historia de Arelis Gomez, luego de dos meses de su cirugía de Mamoplastia de Aumento, y descubre cómo Planmed facilitó su proceso.",coverImage:"/images/branding/logo_fondo_transparente.png",content:"<p>Arelis Gomez, luego de dos meses de su cirugía de Mamoplastia de Aumento nos comparte su increíble resultado.</p><p>Su proceso de recuperación ha sido excelente y su confianza se ha renovado por completo.</p><p>¿Deseas financiar tu cirugía? Mira nuestro video para conocer cómo funciona nuestro modelo y únete a nuestra comunidad de pacientes felices.</p>",publishedAt:"2021-04-26T17:52:21+00:00",author:"Prisly",youtubeUrl:"https://www.youtube.com/embed/tPAVprOsJF0",instagramUrl:"https://www.instagram.com/p/CL7pTzuLxg4/"}];let s=[...t];class c{async getNews(){return[...s]}async getNewsBySlug(e){return s.find(n=>n.slug===e)||null}async createNews(e){const a=String(Math.max(0,...s.map(o=>parseInt(o.id)||0))+1),n=e.title.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-");if(s.some(o=>o.slug===n))throw new Error("Ya existe una noticia con un título similar (slug duplicado).");const i={...e,id:a,slug:n};return s.push(i),i}async updateNews(e,a){const n=s.findIndex(o=>o.slug===e);if(n===-1)throw new Error("Noticia no encontrada");if(a.slug&&a.slug!==e&&s.some(o=>o.slug===a.slug))throw new Error("El slug indicado ya está en uso.");const i={...s[n],...a};return s[n]=i,i}async deleteNews(e){const a=s.findIndex(n=>n.slug===e);return a===-1?!1:(s.splice(a,1),!0)}}class u{constructor(e){this.provider=e||new c}async getNews(){return this.provider.getNews()}async getNewsBySlug(e){return this.provider.getNewsBySlug(e)}async createNews(e){return this.provider.createNews(e)}async updateNews(e,a){return this.provider.updateNews(e,a)}async deleteNews(e){return this.provider.deleteNews(e)}}const d=new u;export{d as n};
